use std::borrow::Borrow;

use crate::error::{Error, ErrorCode};

const FIFO_SUFFIX: &str = ".fifo";

/// A queue name that satisfies the naming rules.
///
/// Lookups take plain `&str` (via `Borrow`): a string that is not a valid
/// name simply names no queue.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct QueueName(String);

impl QueueName {
    pub fn parse(raw: &str) -> Result<Self, Error> {
        let (stem, max_len) = match raw.strip_suffix(FIFO_SUFFIX) {
            Some(stem) => (stem, 75),
            None => (raw, 80),
        };
        let valid = (1..=max_len).contains(&stem.len())
            && stem.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-');
        if valid {
            Ok(Self(raw.to_owned()))
        } else {
            Err(Error::new(ErrorCode::QueueNameInvalid, format!("invalid queue name {raw:?}")))
        }
    }

    pub fn has_fifo_suffix(&self) -> bool {
        self.0.ends_with(FIFO_SUFFIX)
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl Borrow<str> for QueueName {
    fn borrow(&self) -> &str {
        &self.0
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn accepts_and_rejects_names() {
        let long_ok = "a".repeat(75) + ".fifo";
        let long_bad = "a".repeat(76) + ".fifo";
        let plain_ok = "a".repeat(80);
        let plain_bad = "a".repeat(81);
        let cases = [
            ("jobs", true),
            ("A_b-9", true),
            ("jobs.fifo", true),
            (long_ok.as_str(), true),
            (plain_ok.as_str(), true),
            ("", false),
            (".fifo", false),
            ("a.b", false),
            ("jobs.fifo.fifo", false),
            ("a b", false),
            ("caf\u{e9}", false),
            (long_bad.as_str(), false),
            (plain_bad.as_str(), false),
        ];
        for (name, ok) in cases {
            assert_eq!(QueueName::parse(name).is_ok(), ok, "{name:?}");
        }
    }
}
